UPDATE ai_tool SET sql_template = 'SELECT b.batch_code AS 批次号, m.material_name AS 物料, b.qty AS 批次数量, b.qty_unit AS 单位, b.expire_date AS 到期日期, DATEDIFF(b.expire_date, CURDATE()) AS 剩余天数, CASE b.batch_status WHEN ''0'' THEN ''待检'' WHEN ''1'' THEN ''合格'' WHEN ''2'' THEN ''冻结'' WHEN ''3'' THEN ''报废'' ELSE b.batch_status END AS 状态 FROM food_batch b LEFT JOIN wms_material m ON b.material_id = m.material_id WHERE b.expire_date IS NOT NULL AND b.del_flag = ''0'' AND DATEDIFF(b.expire_date, CURDATE()) <= IFNULL(:days, 30) ORDER BY b.expire_date ASC LIMIT 50'
WHERE tool_name = 'getExpiringBatchAdvice';
